# ============================================================================
# 6.1 GERAÇÃO DE RELATÓRIO EXCEL (formatado, para a aba de Emissão)
# ============================================================================
_THIN = Side(style="thin", color="FFD9DDE3")

EXCEL_STYLE = {
    "fill_title": PatternFill(fill_type="solid", start_color="FF0B0E14", end_color="FF0B0E14"),
    "fill_header": PatternFill(fill_type="solid", start_color="FF1A1F2E", end_color="FF1A1F2E"),
    "fill_zebra": PatternFill(fill_type="solid", start_color="FFF3F5F9", end_color="FFF3F5F9"),
    "fill_group": PatternFill(fill_type="solid", start_color="FFEFF3FA", end_color="FFEFF3FA"),
    "fill_total": PatternFill(fill_type="solid", start_color="FFDCE8FF", end_color="FFDCE8FF"),
    "font_title": Font(color="FFFFFFFF", bold=True, size=13, name="Calibri"),
    "font_header": Font(color="FFFFFFFF", bold=True, size=11, name="Calibri"),
    "font_normal": Font(color="FF1F2937", size=10.5, name="Calibri"),
    "font_bold": Font(color="FF1F2937", bold=True, size=10.5, name="Calibri"),
    "font_pos": Font(color="FF1B8A5A", size=10.5, name="Calibri"),
    "font_neg": Font(color="FFC0392B", size=10.5, name="Calibri"),
    "font_caption": Font(color="FF6B7280", italic=True, size=9.5, name="Calibri"),
    "border": Border(left=_THIN, right=_THIN, top=_THIN, bottom=_THIN),
}


def _fonte_por_valor(valor, negrito=False):
    """Verde para positivo, vermelho para negativo. Com `negrito`, devolve a
    mesma cor em negrito -- usado nas linhas de subtotal, que precisam do
    destaque sem perder a leitura do sinal."""
    cor = "FF1B8A5A" if valor >= 0 else "FFC0392B"
    if negrito:
        return Font(color=cor, bold=True, size=10.5, name="Calibri")
    return EXCEL_STYLE["font_pos"] if valor >= 0 else EXCEL_STYLE["font_neg"]


def _escrever_titulo(ws, texto, linha, n_colunas):
    ws.merge_cells(start_row=linha, start_column=1, end_row=linha, end_column=n_colunas)
    cell = ws.cell(row=linha, column=1, value=texto)
    cell.font = EXCEL_STYLE["font_title"]
    cell.fill = EXCEL_STYLE["fill_title"]
    cell.alignment = Alignment(horizontal="left", vertical="center", indent=1)
    ws.row_dimensions[linha].height = 26


def _escrever_legenda(ws, texto, linha, n_colunas):
    ws.merge_cells(start_row=linha, start_column=1, end_row=linha, end_column=n_colunas)
    cell = ws.cell(row=linha, column=1, value=texto)
    cell.font = EXCEL_STYLE["font_caption"]
    cell.alignment = Alignment(horizontal="left", vertical="center", indent=1)
    ws.row_dimensions[linha].height = 16


def _escrever_cabecalho_matriz(ws, linha, primeiro_rotulo, mapa_meses, fill_header=None):
    """Escreve um cabeçalho no formato: [primeiro_rotulo, Jan, Fev, ..., Total Ano]."""
    headers = [primeiro_rotulo] + [m.capitalize() for m in mapa_meses.keys()] + ["Total do período"]
    fill = fill_header or EXCEL_STYLE["fill_zebra"]
    for col, texto in enumerate(headers, start=1):
        cell = ws.cell(row=linha, column=col, value=texto)
        cell.font = EXCEL_STYLE["font_bold"]
        cell.fill = fill
        cell.border = EXCEL_STYLE["border"]
        cell.alignment = Alignment(horizontal="left" if col == 1 else "center")
    return len(headers)


def _escrever_linha_matriz(ws, linha, rotulo, valores_mes, total, negrito=False, fill=None, colorir_por_sinal=False):
    """Escreve uma linha: [rotulo, valor_mes_1, valor_mes_2, ..., total]."""
    valores = [rotulo] + list(valores_mes) + [total]
    for col, val in enumerate(valores, start=1):
        cell = ws.cell(row=linha, column=col, value=val)
        cell.border = EXCEL_STYLE["border"]
        if fill:
            cell.fill = fill
        if col == 1:
            cell.font = EXCEL_STYLE["font_bold"] if negrito else EXCEL_STYLE["font_normal"]
            cell.alignment = Alignment(horizontal="left", vertical="center", indent=1)
        else:
            valor_numerico = val if isinstance(val, (int, float)) else 0
            if colorir_por_sinal:
                cell.font = _fonte_por_valor(valor_numerico)
            else:
                cell.font = EXCEL_STYLE["font_bold"] if negrito else EXCEL_STYLE["font_normal"]
            cell.number_format = '"R$" #,##0.00'
            cell.alignment = Alignment(horizontal="right")


def _escrever_linha_flat(ws, linha, campos, valores_mes, total, negrito=False, fill=None, colorir_por_sinal=False):
    """Escreve uma linha em formato tabular "achatado": [campo_1, campo_2,
    ..., valor_mes_1, ..., total]. `campos` é uma lista de rótulos (ex.:
    [loja, conta, tipo]) -- diferente de _escrever_linha_matriz, que só
    aceita um único rótulo. Usado nas abas que precisam de AutoFilter do
    Excel (uma "loja" por coluna própria, não misturada dentro do texto)."""
    n_campos = len(campos)
    valores = list(campos) + list(valores_mes) + [total]
    for col, val in enumerate(valores, start=1):
        cell = ws.cell(row=linha, column=col, value=val)
        cell.border = EXCEL_STYLE["border"]
        if fill:
            cell.fill = fill
        if col <= n_campos:
            cell.font = EXCEL_STYLE["font_bold"] if negrito else EXCEL_STYLE["font_normal"]
            cell.alignment = Alignment(horizontal="left", vertical="center")
        else:
            valor_numerico = val if isinstance(val, (int, float)) else 0
            if colorir_por_sinal:
                cell.font = _fonte_por_valor(valor_numerico)
            else:
                cell.font = EXCEL_STYLE["font_bold"] if negrito else EXCEL_STYLE["font_normal"]
            cell.number_format = '"R$" #,##0.00'
            cell.alignment = Alignment(horizontal="right")


_CARACTERES_INVALIDOS_ABA = set('[]:*?/\\')


def _nome_aba_seguro(texto, usados, max_len=31):
    """Gera um nome de aba do Excel válido (até 31 caracteres, sem os
    caracteres proibidos pelo Excel) e garante que não colida com nenhum
    outro nome de aba já usado no mesmo workbook (guardados em `usados`,
    em minúsculas)."""
    limpo = "".join(c for c in str(texto) if c not in _CARACTERES_INVALIDOS_ABA).strip()
    limpo = limpo[:max_len] if limpo else "Aba"
    base = limpo
    sufixo = 1
    while limpo.lower() in usados:
        sufixo += 1
        marcador = f"_{sufixo}"
        corte = max_len - len(marcador)
        limpo = f"{base[:corte]}{marcador}"
    usados.add(limpo.lower())
    return limpo


def _ref_aba(nome):
    """Formata o nome de uma aba para uso em fórmulas do Excel (entre aspas
    simples, com aspas simples internas escapadas)."""
    return "'" + str(nome).replace("'", "''") + "'"


def _filtrar_diario_completo(df_diario, loja, conta, plano):
    """Filtra o DIÁRIO por loja (Centro de Custos) + Linha DRE (conta) +
    Plano de Contas exato -- usado para montar a aba de detalhamento dos
    lançamentos ao "clicar" numa linha da aba Plano de Contas."""
    df_filtrado = _filtrar_diario_por_loja_e_conta(df_diario, loja, conta)
    if df_filtrado is None or df_filtrado.empty:
        return df_filtrado
    plano_norm = _normalizar_texto(plano)
    planos_norm = df_filtrado["Plano de Contas"].map(_normalizar_texto)
    mask = planos_norm == plano_norm
    if not mask.any():
        mask = planos_norm.apply(lambda x: (plano_norm in x) or (x in plano_norm) if x else False)
    return df_filtrado[mask]


def _criar_aba_lancamentos(wb, nomes_usados, titulo_bloco, df_lancamentos):
    """Cria uma aba nova com o detalhamento dos lançamentos do DIÁRIO que
    compõem um valor (usada para o "clique" que abre o detalhamento a partir
    da aba Detalhe Mensal ou Plano de Contas). É basicamente uma cópia da
    própria aba DIÁRIO, só que filtrada para aqueles lançamentos específicos
    -- por isso mantém as mesmas colunas dela (Competência, Centro de Custos,
    Linha DRE, Plano de Contas, Valor Bruto). Retorna o nome da aba criada."""
    nome_aba = _nome_aba_seguro(f"Lc_{titulo_bloco}", nomes_usados)
    ws = wb.create_sheet(nome_aba)
    ws.sheet_properties.tabColor = "FF4C8DFF"

    n_col = 5
    _escrever_titulo(ws, f"Lançamentos — {titulo_bloco}"[:250], 1, n_col)
    _escrever_legenda(ws, f"{len(df_lancamentos)} lançamento(s) encontrados na aba DIÁRIO (Realizado).", 2, n_col)

    linha = 4
    headers = ["Competência", "Centro de Custos", "Linha DRE", "Plano de Contas", "Valor Bruto (R$)"]
    for col, texto in enumerate(headers, start=1):
        cell = ws.cell(row=linha, column=col, value=texto)
        cell.font = EXCEL_STYLE["font_header"]
        cell.fill = EXCEL_STYLE["fill_header"]
        cell.border = EXCEL_STYLE["border"]
        cell.alignment = Alignment(horizontal="left" if col in (1, 2, 3, 4) else "center")
    linha += 1

    df_ordenado = df_lancamentos.sort_values("Competência", na_position="last")
    for i, (_, row) in enumerate(df_ordenado.iterrows()):
        data_val = row["Competência"]
        data_txt = data_val.strftime("%d/%m/%Y") if pd.notna(data_val) and hasattr(data_val, "strftime") else str(data_val)
        valores = [data_txt, row["Centro de Custos"], row["Linha DRE"], row["Plano de Contas"], row["Valor Bruto"]]
        fill = EXCEL_STYLE["fill_zebra"] if i % 2 == 1 else None
        for col, val in enumerate(valores, start=1):
            cell = ws.cell(row=linha, column=col, value=val)
            cell.border = EXCEL_STYLE["border"]
            if fill:
                cell.fill = fill
            if col == 5:
                cell.font = EXCEL_STYLE["font_normal"]
                cell.number_format = '"R$" #,##0.00'
                cell.alignment = Alignment(horizontal="right")
            else:
                cell.font = EXCEL_STYLE["font_normal"]
                cell.alignment = Alignment(horizontal="left")
        linha += 1

    total_valor = df_ordenado["Valor Bruto"].sum()
    cell_total_lbl = ws.cell(row=linha, column=1, value="TOTAL")
    cell_total_lbl.font = EXCEL_STYLE["font_bold"]
    cell_total = ws.cell(row=linha, column=5, value=total_valor)
    cell_total.font = EXCEL_STYLE["font_bold"]
    cell_total.number_format = '"R$" #,##0.00'
    cell_total.alignment = Alignment(horizontal="right")
    for col in range(1, n_col + 1):
        ws.cell(row=linha, column=col).fill = EXCEL_STYLE["fill_total"]
        ws.cell(row=linha, column=col).border = EXCEL_STYLE["border"]

    ws.column_dimensions["A"].width = 16
    ws.column_dimensions["B"].width = 22
    ws.column_dimensions["C"].width = 30
    ws.column_dimensions["D"].width = 34
    ws.column_dimensions["E"].width = 18
    ws.freeze_panes = "A5"
    return nome_aba


# ---------------------------------------------------------------------------
# ABA ESPECIAL DO MODELO DE MKT — "1% x Outras Despesas de Marketing"
# ---------------------------------------------------------------------------
# É o relatório que a Controladoria manda para o gestor de MKT. Os quatro
# blocos usam SEMPRE a mesma linha da DRE ("6.24.2 - Marketing Regional -
# Gestão CP"); o que muda é a visão de onde o valor é lido:
#     LOJA - 1%                                  -> aba LJ CONSOLIDADO
#     VD + ABPR (OUTRAS DESPESAS DE MKT)         -> abas VD CONSOLIDADO +
#                                                   ABPR CONSOLIDADO (somadas)
#     CONSOLIDADO: 1% + OUTRAS DESPESAS DE MKT   -> aba DRE CONSOLIDADO
#
# ORÇADO é sempre a linha 6.24.2 pura, sem desconto nenhum, em todos os blocos.
#
# A única particularidade está no REALIZADO do bloco "LOJA - 1%": ele é a
# linha 6.24.2 MENOS "6.24.2.5 - Encontro de Ciclo" e MENOS "6.24.2.6 -
# Outras Despesas de Marketing". Essas duas não fazem parte do 1% e vão para
# os quadros amarelos ao lado ("Outras Despesas de MKT - Canal Loja"),
# justamente para não somarem junto. A conferência é essa: mês a mês,
# LOJA-1% + (VD + ABPR) + quadro amarelo = bloco CONSOLIDADO.
#
# DIFERENÇA = REALIZADO - ORÇADO (como os valores são negativos, diferença
# positiva significa que gastou MENOS do que o orçado).
# ---------------------------------------------------------------------------
COD_MKT_GESTAO_CP = "6.24.2"
CODS_MKT_FORA_DO_1PCT = ["6.24.2.5", "6.24.2.6"]
NOME_MKT_GESTAO_CP_PADRAO = "6.24.2 - Marketing Regional - Gestão CP"

# (título do bloco, abas de origem, desconta as linhas que ficam fora do 1%?)
# VD e ABPR ficam SOMADOS num bloco só: os dois canais são lidos e os valores
# somados mês a mês antes de ir para a planilha.
BLOCOS_MKT_1PCT = [
    ("LOJA - 1%", ["LJ CONSOLIDADO"], True),
    ("VD + ABPR (OUTRAS DESPESAS DE MKT)", ["VD CONSOLIDADO", "ABPR CONSOLIDADO"], False),
    ("CONSOLIDADO: 1% + OUTRAS DESPESAS DE MKT", ["DRE CONSOLIDADO"], False),
]
# Lista achatada das abas usadas, sem repetir, para o carregamento dos dados.
VISOES_ABA_MKT_1PCT = list(dict.fromkeys(
    nome_aba for _, abas, _ in BLOCOS_MKT_1PCT for nome_aba in abas
))

_MKT_FILL_HEADER = PatternFill(fill_type="solid", start_color="FF5B9BD5", end_color="FF5B9BD5")
_MKT_FILL_LINHA = PatternFill(fill_type="solid", start_color="FFDDEBF7", end_color="FFDDEBF7")
_MKT_FILL_AMARELO = PatternFill(fill_type="solid", start_color="FFFFFF00", end_color="FFFFFF00")
_MKT_FONT_TITULO = Font(bold=True, italic=True, size=11, color="FF000000", name="Calibri")
_MKT_FONT_HEADER = Font(bold=True, italic=True, size=11, color="FF000000", name="Calibri")
_MKT_FONT_ROTULO = Font(bold=True, italic=True, size=11, color="FF000000", name="Calibri")
_MKT_FONT_CONTA = Font(italic=True, size=11, color="FFC00000", name="Calibri")
_MKT_FONT_VALOR = Font(size=11, color="FFC00000", name="Calibri")
_MKT_FONT_VALOR_TOTAL = Font(bold=True, size=11, color="FFC00000", name="Calibri")
_MKT_FONT_AMARELO = Font(bold=True, size=11, color="FF000000", name="Calibri")
_MKT_FONT_AMARELO_VALOR = Font(size=11, color="FFC00000", name="Calibri")
_MKT_NUM_FMT = '"R$" #,##0.00;-"R$" #,##0.00'


def _nome_linha_por_codigo(df, codigo, padrao=None):
    """Devolve o NOME COMPLETO da linha da DRE cujo código hierárquico é
    EXATAMENTE `codigo` (ex.: "6.24.2" -> "6.24.2 - Marketing Regional -
    Gestão CP"). Comparar o código extraído do início do texto, em vez de
    usar "contém", é o que impede o 6.24.2 de casar também com 6.24.2.5 e
    6.24.2.6 -- que é justamente a diferença entre o valor cheio e o 1%."""
    if df is None or getattr(df, "empty", True):
        return padrao
    col_nome = "Nome" if "Nome" in df.columns else df.columns[0]
    nomes = df[col_nome].dropna().astype(str).str.strip()
    if nomes.empty:
        return padrao
    codigos = nomes.str.extract(r"^(\d+(?:\.\d+)*)", expand=False)
    achados = nomes[codigos == codigo]
    return achados.iloc[0] if not achados.empty else padrao


def _valor_linha_por_codigo(df, codigo, coluna_mes):
    """Soma o valor de UMA linha da DRE (identificada pelo código exato) num
    mês. Devolve 0.0 se a linha ou a coluna do mês não existirem na aba."""
    if df is None or getattr(df, "empty", True):
        return 0.0
    if not coluna_mes or coluna_mes not in df.columns:
        return 0.0
    col_nome = "Nome" if "Nome" in df.columns else df.columns[0]
    nomes = df[col_nome].astype(str).str.strip()
    codigos = nomes.str.extract(r"^(\d+(?:\.\d+)*)", expand=False)
    mask = (codigos == codigo).fillna(False)
    if not mask.any():
        return 0.0
    return float(pd.to_numeric(df.loc[mask, coluna_mes], errors="coerce").fillna(0).sum())


def _somar_codigo_com_filhas(df, codigo, colunas):
    """Soma uma linha da DRE pelo código, caindo nas filhas quando a linha-mãe
    não está preenchida naquela aba.

    Numa DRE a linha-mãe é a soma das filhas, então o total é o mesmo — o que
    muda é ONDE o número foi lançado, e isso varia de aba para aba. No canal
    Loja o orçamento de marketing está na própria 6.24.2; em VD CONSOLIDADO
    ele está nas filhas, e ler só a mãe devolvia zero, fazendo o canal
    aparecer sem orçamento nenhum.

    Só desce para as filhas quando a mãe vem zerada, então não há risco de
    contar o mesmo valor duas vezes."""
    total = sum(_valor_linha_por_codigo(df, codigo, coluna) for coluna in colunas)
    if total or df is None or getattr(df, "empty", True):
        return total

    col_nome = "Nome" if "Nome" in df.columns else df.columns[0]
    codigos = df[col_nome].astype(str).str.strip().str.extract(r"^(\d+(?:\.\d+)*)", expand=False)
    # Só o primeiro nível de filhas: descer mais contaria neto junto com filho.
    filhas = codigos[codigos.fillna("").str.match(rf"^{re.escape(codigo)}\.\d+$")].dropna().unique()
    return sum(
        _valor_linha_por_codigo(df, str(filha), coluna)
        for filha in filhas for coluna in colunas
    )


def _valores_mkt_1pct(dados_visoes, mapa_meses):
    """Calcula, para cada bloco, as listas de REALIZADO / ORÇADO / DIFERENÇA
    mês a mês, mais os valores dos quadros amarelos (o que sai do 1% do canal
    Loja). Separado da escrita do Excel para poder ser conferido sozinho.

    Devolve (blocos, outras_loja, visoes_faltando), onde `blocos` é uma lista
    de dicionários com titulo/abas/nome_conta/realizado/orcado/diferenca."""
    indice_visoes = {_normalizar_nome_aba(k): v for k, v in (dados_visoes or {}).items()}
    meses_cols = list(mapa_meses.values())

    def _dfs_da_visao(nome_visao):
        return indice_visoes.get(_normalizar_nome_aba(nome_visao), (None, None))

    visoes_faltando = [
        nome_aba for nome_aba in VISOES_ABA_MKT_1PCT
        if _normalizar_nome_aba(nome_aba) not in indice_visoes
    ]

    # Quadros amarelos: Encontro de Ciclo + Outras Despesas de Marketing,
    # do canal Loja (LJ CONSOLIDADO), mês a mês.
    _, df_r_lj = _dfs_da_visao("LJ CONSOLIDADO")
    outras_loja = [
        sum(_valor_linha_por_codigo(df_r_lj, cod, m_col) for cod in CODS_MKT_FORA_DO_1PCT)
        for m_col in meses_cols
    ]

    blocos = []
    for titulo, abas_bloco, descontar in BLOCOS_MKT_1PCT:
        dfs_bloco = [_dfs_da_visao(nome_aba) for nome_aba in abas_bloco]
        nome_conta = NOME_MKT_GESTAO_CP_PADRAO
        for df_o_i, df_r_i in dfs_bloco:
            achado = (
                _nome_linha_por_codigo(df_r_i, COD_MKT_GESTAO_CP)
                or _nome_linha_por_codigo(df_o_i, COD_MKT_GESTAO_CP)
            )
            if achado:
                nome_conta = achado
                break

        realizado, orcado = [], []
        for i, m_col in enumerate(meses_cols):
            # Quando o bloco tem mais de uma aba (VD + ABPR), o valor do mês é
            # a soma das abas -- a linha da DRE é a mesma em todas elas.
            valor_real = sum(
                _valor_linha_por_codigo(df_r_i, COD_MKT_GESTAO_CP, m_col)
                for _, df_r_i in dfs_bloco
            )
            if descontar:
                valor_real -= outras_loja[i]
            realizado.append(valor_real)
            orcado.append(sum(
                _valor_linha_por_codigo(df_o_i, COD_MKT_GESTAO_CP, m_col)
                for df_o_i, _ in dfs_bloco
            ))
        blocos.append({
            "titulo": titulo,
            "abas": list(abas_bloco),
            "nome_conta": nome_conta,
            "realizado": realizado,
            "orcado": orcado,
            "diferenca": [r - o for r, o in zip(realizado, orcado)],
        })
    return blocos, outras_loja, visoes_faltando


def _criar_aba_mkt_1pct(wb, dados_visoes, mapa_meses, gerado_em):
    """Monta a aba do relatório de MKT no mesmo layout usado hoje na mão:
    quatro blocos (LOJA - 1%, VD, ABPR e CONSOLIDADO), cada um com REALIZADO,
    ORÇADO e DIFERENÇA por mês, e os quadros amarelos das "Outras Despesas de
    MKT - Canal Loja" na lateral."""
    meses_cols = list(mapa_meses.values())
    n_meses = len(meses_cols)
    if n_meses == 0:
        return None

    blocos, outras_loja, visoes_faltando = _valores_mkt_1pct(dados_visoes, mapa_meses)

    ws = wb.create_sheet("MKT - 1% x Outras Despesas", 1)
    ws.sheet_properties.tabColor = "FFFFC000"
    ws.sheet_view.showGridLines = False

    COL_ROTULO = 1   # A: REALIZADO / ORÇADO / DIFERENÇA
    COL_CONTA = 2    # B: nome da linha da DRE
    COL_MES_1 = 3    # C em diante: um mês por coluna
    col_total = COL_MES_1 + n_meses
    col_lateral = col_total + 3  # quadros amarelos, depois de 2 colunas em branco

    def _escrever_linha_bloco(linha, rotulo, nome_conta, valores):
        cell_rotulo = ws.cell(row=linha, column=COL_ROTULO, value=rotulo)
        cell_rotulo.font = _MKT_FONT_ROTULO
        cell_rotulo.alignment = Alignment(horizontal="left", vertical="center")

        cell_conta = ws.cell(row=linha, column=COL_CONTA, value=nome_conta)
        cell_conta.font = _MKT_FONT_CONTA
        cell_conta.fill = _MKT_FILL_LINHA
        cell_conta.border = EXCEL_STYLE["border"]
        cell_conta.alignment = Alignment(horizontal="left", vertical="center", indent=1)

        for i, valor in enumerate(list(valores) + [sum(valores)]):
            col = COL_MES_1 + i
            cell = ws.cell(row=linha, column=col, value=valor)
            cell.font = _MKT_FONT_VALOR_TOTAL if col == col_total else _MKT_FONT_VALOR
            cell.fill = _MKT_FILL_LINHA
            cell.border = EXCEL_STYLE["border"]
            cell.number_format = _MKT_NUM_FMT
            cell.alignment = Alignment(horizontal="right", vertical="center")

    linha = 1
    for bloco in blocos:
        # Título do bloco (mesclado por cima da tabela)
        ws.merge_cells(start_row=linha, start_column=COL_CONTA, end_row=linha, end_column=col_total)
        cell_titulo = ws.cell(row=linha, column=COL_CONTA, value=bloco["titulo"])
        cell_titulo.font = _MKT_FONT_TITULO
        cell_titulo.alignment = Alignment(horizontal="center", vertical="center")
        linha += 1

        # Cabeçalho: Nome | meses | Total
        cabecalho = ["Nome"] + list(meses_cols) + ["Total"]
        for i, texto in enumerate(cabecalho):
            cell = ws.cell(row=linha, column=COL_CONTA + i, value=texto)
            cell.font = _MKT_FONT_HEADER
            cell.fill = _MKT_FILL_HEADER
            cell.border = EXCEL_STYLE["border"]
            cell.alignment = Alignment(horizontal="center", vertical="center")
        ws.row_dimensions[linha].height = 20
        linha += 1

        _escrever_linha_bloco(linha, "REALIZADO", bloco["nome_conta"], bloco["realizado"])
        linha += 1
        _escrever_linha_bloco(linha, "ORÇADO", bloco["nome_conta"], bloco["orcado"])
        linha += 1
        _escrever_linha_bloco(linha, "DIFERENÇA", bloco["nome_conta"], bloco["diferenca"])
        linha += 3  # duas linhas em branco entre um bloco e outro

    ultima_linha_blocos = linha - 3

    # ---- Quadros amarelos: o que sai do 1% do canal Loja, mês a mês ----
    linha_lateral = 2
    for i, nome_mes in enumerate(mapa_meses.keys()):
        cell_lbl = ws.cell(
            row=linha_lateral, column=col_lateral,
            value=f"Outras Despesas de MKT - Canal Loja ({nome_mes.capitalize()})",
        )
        cell_lbl.font = _MKT_FONT_AMARELO
        cell_lbl.fill = _MKT_FILL_AMARELO
        cell_lbl.alignment = Alignment(horizontal="left", vertical="center")

        cell_val = ws.cell(row=linha_lateral + 1, column=col_lateral, value=outras_loja[i])
        cell_val.font = _MKT_FONT_AMARELO_VALOR
        cell_val.fill = _MKT_FILL_AMARELO
        cell_val.number_format = _MKT_NUM_FMT
        cell_val.alignment = Alignment(horizontal="left", vertical="center")
        linha_lateral += 3

    # ---- Rodapé: como o número é montado (fica abaixo de tudo, sem
    # atrapalhar o layout que o gestor já conhece) ----
    linha_rodape = max(ultima_linha_blocos, linha_lateral) + 2
    notas = [
        gerado_em,
        "LOJA - 1% (Realizado) = linha 6.24.2 na aba LJ CONSOLIDADO, menos 6.24.2.5 (Encontro de Ciclo) "
        "e 6.24.2.6 (Outras Despesas de Marketing) -- esses dois estão nos quadros amarelos ao lado.",
        "VD + ABPR (Realizado) = linha 6.24.2 na aba VD CONSOLIDADO MAIS a mesma linha na aba "
        "ABPR CONSOLIDADO, somadas, sem desconto. CONSOLIDADO = linha 6.24.2 na aba DRE CONSOLIDADO. "
        "Orçado = linha 6.24.2 pura em todos os blocos.",
        "Conferência: em cada mês, LOJA-1% + (VD + ABPR) + quadro amarelo = CONSOLIDADO.",
        "DIFERENÇA = Realizado - Orçado (valores negativos são despesa; diferença positiva = gastou menos que o orçado).",
    ]
    if visoes_faltando:
        notas.append(
            "ATENÇÃO: não encontrei a(s) aba(s) " + ", ".join(visoes_faltando)
            + " nas planilhas -- o(s) bloco(s) correspondente(s) saiu(ram) zerado(s)."
        )
    for nota in notas:
        cell = ws.cell(row=linha_rodape, column=COL_ROTULO, value=nota)
        cell.font = EXCEL_STYLE["font_caption"]
        cell.alignment = Alignment(horizontal="left", vertical="center")
        linha_rodape += 1

    # ---- Larguras ----
    ws.column_dimensions[get_column_letter(COL_ROTULO)].width = 14
    ws.column_dimensions[get_column_letter(COL_CONTA)].width = 42
    for col in range(COL_MES_1, col_total + 1):
        ws.column_dimensions[get_column_letter(col)].width = 16
    ws.column_dimensions[get_column_letter(col_lateral)].width = 46
    return ws


def resolver_planos_forcados(df_diario, termos):
    """Acha, na aba DIÁRIO, os planos de contas que um modelo exige pelo NOME.

    Alguns modelos têm planos que precisam sair no relatório mesmo sem uma
    linha da DRE apontando para eles (o caso de "Mercadorias", em Compras, e
    das benfeitorias, em Suprimentos). Como esses planos não são alcançados
    pela busca a partir das linhas da DRE, eles são resolvidos aqui, direto
    pelo nome.

    A comparação é tolerante: primeiro o nome exato (normalizado) e, se não
    achar, aceita o plano que contenha o termo -- a grafia na planilha muda
    com o tempo e um acento a mais não pode derrubar o item do relatório.

    Devolve (encontrados, nao_encontrados) para a tela poder avisar quando um
    termo do modelo não existe mais na DIÁRIO."""
    if df_diario is None or df_diario.empty or "Plano de Contas" not in df_diario.columns:
        return [], list(termos or [])
    disponiveis = (
        df_diario["Plano de Contas"].dropna().astype(str).str.strip().unique().tolist()
    )
    # "RESTANTE" (ADM/Financeiro): os planos sem linha da DRE que nenhum
    # outro modelo puxou pelo nome. Sem isso, esses lançamentos não apareciam
    # em relatório nenhum -- não têm linha da DRE que os alcance, e só os de
    # Compras e Suprimentos estavam listados à mão.
    if "RESTANTE" in (termos or []):
        termos = [t for t in termos if t != "RESTANTE"]
        ja_reivindicados = set()
        for modelo in MODELOS_RELATORIO.values():
            for plano in modelo.get("forcar_planos_contas", []):
                if plano != "RESTANTE":
                    ja_reivindicados.add(_normalizar_texto(plano))
        termos = list(termos) + [
            p for p in _planos_sem_linha_dre(df_diario)
            if _normalizar_texto(p) not in ja_reivindicados
        ]
    indice = {_normalizar_texto(p): p for p in disponiveis}
    encontrados, faltando = [], []
    for termo in (termos or []):
        chave = _normalizar_texto(termo)
        if chave in indice:
            encontrados.append(indice[chave])
            continue
        parecidos = [nome for norm, nome in indice.items() if chave and chave in norm]
        if parecidos:
            encontrados.extend(parecidos)
        else:
            faltando.append(termo)
    return list(dict.fromkeys(encontrados)), faltando


def planos_do_diario(df_diario, linhas_dre=None):
    """Lista os planos de contas que EXISTEM na aba DIÁRIO.

    Quando `linhas_dre` é informado, devolve só os planos que aparecem
    naquelas linhas da DRE -- é assim que cada modelo de departamento oferece
    apenas os planos que de fato pertencem a ele, em vez da lista inteira da
    empresa. A comparação é pelo texto normalizado, porque o nome da linha na
    DRE e na DIÁRIO costuma ter pequenas diferenças de digitação."""
    if df_diario is None or df_diario.empty or "Plano de Contas" not in df_diario.columns:
        return []
    base = df_diario
    if linhas_dre:
        if "Linha DRE" not in df_diario.columns:
            return []
        alvo = {_normalizar_texto(l) for l in linhas_dre}
        base = df_diario[df_diario["Linha DRE"].map(_normalizar_texto).isin(alvo)]
    planos = base["Plano de Contas"].dropna().astype(str).str.strip()
    planos = planos[planos != ""]
    return sorted(planos.unique().tolist())


def _criar_aba_resumo_anual(wb, nomes_usados, nome_visao, df_orc, df_real,
                            mapa_meses, contas_sel, gerado_em):
    """Uma aba por visão consolidada, no formato que a coordenação já usava na
    mão: as linhas da DRE nas linhas, os meses nas colunas, e cada mês aberto
    em ORÇADO e REALIZADO. Fecha com o percentual do EBITDA sobre a receita
    líquida, mês a mês.

    O percentual é a leitura que importa aqui: o EBITDA em reais sobe junto
    com a venda, e só a margem mostra se a unidade ficou mais eficiente. Ele é
    calculado mês a mês -- não é a média dos meses, que daria outro número
    quando o faturamento é desigual entre eles."""
    nome_aba = _nome_aba_seguro(f"Anual - {nome_visao}", nomes_usados)
    ws = wb.create_sheet(nome_aba)
    ws.sheet_properties.tabColor = "FF1B8A5A"

    meses = list(mapa_meses.items())
    n_col = 1 + len(meses) * 2 + 2  # DRE + (orçado, realizado) por mês + total

    _escrever_titulo(ws, f"Resumo Anual — {nome_visao}", 1, n_col)
    _escrever_legenda(
        ws,
        f"{gerado_em} · Todos os meses disponíveis na planilha, independentemente do período "
        f"escolhido para as outras abas. Cada mês em Orçado e Realizado; a última linha traz o "
        f"EBITDA em % da Receita Operacional Líquida, calculado mês a mês.",
        2, n_col,
    )

    # Cabeçalho em duas faixas: o mês por cima, Orçado/Realizado por baixo.
    linha_mes, linha_sub = 4, 5
    cabecalho = ws.cell(row=linha_mes, column=1, value="DRE")
    cabecalho.font = EXCEL_STYLE["font_header"]
    cabecalho.fill = EXCEL_STYLE["fill_header"]
    cabecalho.border = EXCEL_STYLE["border"]
    ws.merge_cells(start_row=linha_mes, start_column=1, end_row=linha_sub, end_column=1)
    cabecalho.alignment = Alignment(horizontal="left", vertical="center")

    col = 2
    for rotulo, _col_mes in meses + [("TOTAL", None)]:
        ws.merge_cells(start_row=linha_mes, start_column=col, end_row=linha_mes, end_column=col + 1)
        celula = ws.cell(row=linha_mes, column=col, value=str(rotulo).upper())
        celula.font = EXCEL_STYLE["font_header"]
        celula.fill = EXCEL_STYLE["fill_header"]
        celula.border = EXCEL_STYLE["border"]
        celula.alignment = Alignment(horizontal="center", vertical="center")
        for deslocamento, texto_sub in enumerate(("ORÇADO", "REALIZADO")):
            sub = ws.cell(row=linha_sub, column=col + deslocamento, value=texto_sub)
            sub.font = EXCEL_STYLE["font_header"]
            sub.fill = EXCEL_STYLE["fill_header"]
            sub.border = EXCEL_STYLE["border"]
            sub.alignment = Alignment(horizontal="center")
        col += 2
    ws.row_dimensions[linha_mes].height = 18
    ws.freeze_panes = f"B{linha_sub + 1}"

    dfs_r = [df_real] if df_real is not None else []
    dfs_o = [df_orc] if df_orc is not None else []

    def _serie(dfs, conta):
        return [get_valor_consolidado_multi(dfs, conta, [c]) for _r, c in meses]

    linha = linha_sub + 1
    valores_por_conta = {}
    for i, conta in enumerate(contas_sel):
        serie_real = _serie(dfs_r, conta)
        serie_orc = _serie(dfs_o, conta)
        valores_por_conta[_numero_linha_dre(conta)] = (serie_orc, serie_real)
        if not any(serie_real) and not any(serie_orc):
            continue
        fill = EXCEL_STYLE["fill_zebra"] if i % 2 == 1 else None
        celula = ws.cell(row=linha, column=1, value=conta)
        celula.font = EXCEL_STYLE["font_normal"]
        celula.fill = fill or PatternFill(fill_type=None)
        celula.border = EXCEL_STYLE["border"]
        celula.alignment = Alignment(horizontal="left", vertical="center", indent=1)
        col = 2
        for valor_orc, valor_real in list(zip(serie_orc, serie_real)) + [
            (sum(serie_orc), sum(serie_real))
        ]:
            for deslocamento, valor in enumerate((valor_orc, valor_real)):
                alvo = ws.cell(row=linha, column=col + deslocamento, value=valor)
                alvo.font = _fonte_por_valor(valor)
                alvo.number_format = '"R$" #,##0.00'
                alvo.border = EXCEL_STYLE["border"]
                alvo.alignment = Alignment(horizontal="right")
                if fill:
                    alvo.fill = fill
            col += 2
        linha += 1

    # ---- Linha final: EBITDA em % da receita líquida ----
    ebitda = valores_por_conta.get(str(GRUPO_EBITDA_DRE))
    receita = valores_por_conta.get("3")
    if ebitda and receita:
        linha += 1
        celula = ws.cell(row=linha, column=1, value=f"{GRUPO_EBITDA_DRE} - EBITDA (%)")
        celula.font = EXCEL_STYLE["font_bold"]
        celula.fill = EXCEL_STYLE["fill_total"]
        celula.border = EXCEL_STYLE["border"]
        celula.alignment = Alignment(horizontal="left", vertical="center", indent=1)

        def _percentuais(indice):
            # Mês a mês, e o total sobre o total -- não a média dos meses.
            pares = list(zip(ebitda[indice], receita[indice]))
            pares.append((sum(ebitda[indice]), sum(receita[indice])))
            return [(e / r * 100) if r else 0.0 for e, r in pares]

        pct_orc, pct_real = _percentuais(0), _percentuais(1)
        col = 2
        for valor_orc, valor_real in zip(pct_orc, pct_real):
            for deslocamento, valor in enumerate((valor_orc, valor_real)):
                alvo = ws.cell(row=linha, column=col + deslocamento, value=valor)
                alvo.font = EXCEL_STYLE["font_bold"]
                alvo.number_format = '0"%"'
                alvo.fill = EXCEL_STYLE["fill_total"]
                alvo.border = EXCEL_STYLE["border"]
                alvo.alignment = Alignment(horizontal="right")
            col += 2
        linha += 2
        _escrever_legenda(
            ws,
            "EBITDA (%) = EBITDA do mês dividido pela Receita Operacional Líquida do mesmo mês. "
            "A coluna TOTAL usa o acumulado do período, não a média dos meses — com faturamento "
            "desigual entre eles, as duas contas dão resultados diferentes.",
            linha, n_col,
        )

    ws.column_dimensions["A"].width = 42
    for indice in range(2, n_col + 1):
        ws.column_dimensions[get_column_letter(indice)].width = 16
    return nome_aba


def montar_relatorio_excel(
    contas_sel,
    dfs_real,
    dfs_orc,
    mapa_meses,
    colunas_ano,
    escopo_label,
    dados_por_loja=None,
    mapa_planos_dre=None,
    df_diario=None,
    forcar_planos_contas=None,
    permitir_lancamento_manual=False,
    mapa_loja_centro_custo=None,
    dados_visoes_mkt=None,
    incluir_aba_mkt_1pct=False,
    planos_filtro=None,
    blocos_agrupados=None,
    linha_percentual_ebitda=False,
    resumos_anuais=None,
    mapa_meses_anual=None,
    apenas_planos_com_linha_dre=False,
):
    """Gera um relatório Excel formatado com três planilhas:
    - Resumo: total do ano por conta, CONSOLIDADO (não muda com a divisão por loja).
    - Detalhe Mensal: contas da DRE nas linhas, meses nas colunas, dividido por loja.
    - Plano de Contas: composição (planos de contas) de cada linha da DRE, por loja,
      mês a mês. Fonte principal: aba DIÁRIO da planilha Realizado 2026 (df_diario).
      Se o DIÁRIO não estiver disponível para uma loja/conta, cai para o método
      antigo (Tabela_Contas + soma nas abas por loja).

    forcar_planos_contas: lista de nomes de Plano de Contas que devem ser
    incluídos na aba "Plano de Contas" à parte, puxados direto pelo nome
    (ignorando a Linha DRE) -- usado por modelos como o de Compras, onde
    "Mercadorias" faz parte do relatório mesmo sem linha da DRE correspondente.

    permitir_lancamento_manual: quando True, uma Linha DRE sem nenhum Plano
    de Contas correspondente no DIÁRIO/Tabela_Contas aparece como
    "Lançado Manualmente", com o valor da própria linha da DRE -- usado pelo
    modelo de RH, que tem várias linhas lançadas direto, sem plano de contas.

    mapa_loja_centro_custo: {nome_da_loja: centro_de_custo}, vindo da
    Tabela_Lojas (DE_PARA). A DIÁRIO identifica a loja pelo Centro de Custos,
    que normalmente é diferente do nome da aba da loja -- por isso, sempre
    que formos filtrar a DIÁRIO por loja, resolvemos primeiro o nome da loja
    para o Centro de Custos correspondente por esse mapa (usando o próprio
    nome da loja como alternativa, caso não haja correspondência no DE_PARA).
    """
    dados_por_loja = dados_por_loja or {}
    mapa_planos_dre = mapa_planos_dre or {}
    forcar_planos_contas = forcar_planos_contas or []
    # Quando a pessoa filtra por plano de contas, o relatório é o MESMO --
    # mesmas abas, mesmos cabeçalhos, mesmo nome de arquivo. O que muda é a
    # origem dos valores: em vez de virem das abas por loja (que só sabem
    # somar a linha da DRE inteira), vêm da DIÁRIO, lançamento a lançamento,
    # restrita aos planos escolhidos. É o único jeito de o número refletir
    # apenas o que foi selecionado.
    planos_filtro = planos_filtro or []
    # Blocos do relatório: um subtotal próprio para um punhado de linhas que a
    # área acompanha junto, seguido das linhas que o compõem. É o formato do
    # relatório que a Controladoria já enviava na mão -- na Gerência Comercial,
    # o "Quadro de Metas GER.COM." é a soma de três linhas, e o grupo 6 vem
    # logo abaixo, separado. Sem isso, o Excel saía com tudo numa lista só e o
    # total do quadro não aparecia em lugar nenhum.
    blocos_agrupados = blocos_agrupados or []
    resumos_anuais = resumos_anuais or []
    # Modelo que só responde por linhas da DRE (as coordenações) não deve
    # trazer no Excel lançamento que não passa por nenhuma linha -- eles não
    # compõem nada do que está sendo mostrado e só somam ruído nas abas de
    # Plano de Contas e Lançamentos.
    if apenas_planos_com_linha_dre and df_diario is not None and not df_diario.empty:
        if "Linha DRE" in df_diario.columns:
            df_diario = df_diario[
                ~df_diario["Linha DRE"].map(
                    lambda v: _normalizar_texto(v) in MARCAS_SEM_LINHA_DRE
                )
            ]
    mapa_loja_centro_custo = mapa_loja_centro_custo or {}
    diario_disponivel = df_diario is not None and not df_diario.empty

    def _cc(loja):
        """Resolve os candidatos de Centro de Custos para uma loja: o valor
        mapeado pela Tabela_Lojas (DE_PARA) E o próprio nome da loja/aba,
        nessa ordem. A busca no DIÁRIO tenta os dois, então funciona mesmo
        que o DE_PARA esteja incompleto/não encontrado para alguma loja, ou
        caso o Centro de Custos já seja igual ao nome da loja em alguns
        casos."""
        centro_mapeado = mapa_loja_centro_custo.get(loja)
        candidatos = [c for c in (centro_mapeado, loja) if c]
        return candidatos or [loja]
    wb = Workbook()
    gerado_em = f"{escopo_label} · Gerado em {datetime.now(FUSO_BR).strftime('%d/%m/%Y às %H:%M')}"

    # ========================================================================
    # Dados auxiliares: lojas individuais x visões consolidadas, e o filtro
    # único da DIÁRIO que alimenta tanto a aba "Lançamentos" quanto a aba
    # "Plano de Contas".
    # ========================================================================
    lojas_ordenadas = sorted(dados_por_loja.keys()) if dados_por_loja else []
    meses_chaves = list(mapa_meses.keys())
    n_meses = len(meses_chaves)
    n_col_matriz = 1 + n_meses + 1  # rótulo + meses + Total Ano

    LOJAS_CONSOLIDADAS = {
        "DRE CONSOLIDADO", "ABPR CONSOLIDADO", "VD CONSOLIDADO",
        "LJ CONSOLIDADO", "ABPR + VD", "LJ - G&A", "CONSOLIDADO - G&A",
    }
    _LOJAS_CONSOLIDADAS_NORM = {_normalizar_nome_aba(n) for n in LOJAS_CONSOLIDADAS}
    lojas_individuais = [l for l in lojas_ordenadas if _normalizar_nome_aba(l) not in _LOJAS_CONSOLIDADAS_NORM]

    def _lojas_do_grupo_consolidado(nome_grupo):
        """Para uma "loja" que na verdade é uma visão consolidada (ex.: "ABPR
        + VD"), devolve as lojas INDIVIDUAIS que fazem parte dela -- usado
        para somar corretamente a composição de Plano de Contas (que vem da
        DIÁRIO, que só reconhece lojas individuais, nunca uma visão
        consolidada). Grupos definidos explicitamente:
        - ABPR CONSOLIDADO = ABPR 23427 + ABPR ZNS 24527
        - VD CONSOLIDADO = VD - GUAJARA 23859 + VD - LESTE 21506 + VD - MACHAD 21691 +
          VD - MATRIZ 13967 + VD - VST ALEG 21497
        - ABPR + VD = ABPR CONSOLIDADO + VD CONSOLIDADO
        - LJ - G&A = as 13 lojas "LJ ..." (sem ESCRIT MATRIZ, sem lojas VD)
        - LJ CONSOLIDADO = ESCRIT MATRIZ 6037 + LJ - G&A (sem lojas VD)
        - CONSOLIDADO - G&A = ABPR CONSOLIDADO + VD CONSOLIDADO + LJ - G&A
        - DRE CONSOLIDADO = ABPR CONSOLIDADO + VD CONSOLIDADO + LJ CONSOLIDADO
          (na prática, todas as 21 lojas individuais)
        """
        # Fonte única: VISOES_CONSOLIDADAS, no topo do arquivo. Enquanto este
        # mapa era duplicado aqui dentro, o painel e o Excel podiam discordar
        # sobre quais lojas formam uma visão.
        mapa_grupos_normalizado = {
            _normalizar_nome_aba(k): v for k, v in VISOES_CONSOLIDADAS.items()
        }
        lojas_definidas = mapa_grupos_normalizado.get(_normalizar_nome_aba(nome_grupo), [])
        # Só devolve lojas que realmente existem entre as lojas individuais carregadas.
        return [l for l in lojas_definidas if l in lojas_individuais]


    # ---- Filtra a DIÁRIO para pegar só os lançamentos relevantes deste
    # relatório: linhas cuja "Linha DRE" bate com alguma conta selecionada,
    # OU cujo "Plano de Contas" bate com um dos planos forçados (ex.:
    # "Mercadorias", que não tem Linha DRE). Essa é a ÚNICA fonte usada tanto
    # pela aba "Lançamentos" quanto para montar a composição da aba
    # "Plano de Contas" -- ou seja, os dois batem entre si por construção. ----
    if diario_disponivel:
        linhas_norm = df_diario["Linha DRE"].map(_normalizar_texto)
        mask_conta = pd.Series(False, index=df_diario.index)
        for conta in contas_sel:
            conta_norm = _normalizar_texto(conta)
            m = linhas_norm == conta_norm
            if not m.any():
                m = linhas_norm.apply(lambda x: (conta_norm in x) or (x in conta_norm) if x else False)
            mask_conta |= m

        planos_norm = df_diario["Plano de Contas"].map(_normalizar_texto)
        mask_forcado = pd.Series(False, index=df_diario.index)
        for plano in forcar_planos_contas:
            plano_norm = _normalizar_texto(plano)
            m = planos_norm == plano_norm
            if not m.any():
                m = planos_norm.apply(lambda x: (plano_norm in x) or (x in plano_norm) if x else False)
            mask_forcado |= m

        if planos_filtro:
            # Só os planos marcados -- ignora tanto as linhas da DRE quanto
            # os planos forçados do modelo.
            alvo_planos = {_normalizar_texto(p) for p in planos_filtro}
            mask_planos = planos_norm.isin(alvo_planos)
            df_lanc = df_diario[mask_planos].copy()
        else:
            df_lanc = df_diario[mask_conta | mask_forcado].copy()
        # Resolve o nome "bonito" da loja a partir do Centro de Custos (usa o
        # mapa nos dois sentidos, montado pela Tabela_Lojas/DE_PARA). Se não
        # achar correspondência, mantém o próprio Centro de Custos como
        # rótulo (mais transparente do que esconder a linha).
        df_lanc["Loja"] = df_lanc["Centro de Custos"].astype(str).str.strip().map(
            lambda cc: mapa_loja_centro_custo.get(cc, cc)
        )
    else:
        df_lanc = pd.DataFrame(
            columns=[
                "Competência", "Centro de Custos", "Linha DRE", "Plano de Contas", "Valor Bruto", "Mês",
                "Número", "Cliente / Fornecedor", "Histórico", "Loja",
            ]
        )

    # Com filtro por plano, as linhas do relatório são as que os planos
    # escolhidos alimentam -- e não as do modelo. Plano sem linha da DRE
    # entra como "(Fora da DRE)", exatamente como o relatório padrão já
    # faz na aba Plano de Contas.
    ROTULO_FORA_DA_DRE = "(Fora da DRE)"
    if planos_filtro:
        linhas_encontradas = []
        if not df_lanc.empty:
            achadas = (
                df_lanc["Linha DRE"].dropna().astype(str).str.strip().unique().tolist()
            )
            linhas_encontradas = sorted(l for l in achadas if l)
            tem_sem_linha = (
                df_lanc["Linha DRE"].map(_normalizar_texto) == ""
            ).any()
            if tem_sem_linha:
                linhas_encontradas.append(ROTULO_FORA_DA_DRE)
        contas_sel = linhas_encontradas

    def _valores_planos(conta, meses, lojas=None):
        """Realizado dos planos filtrados, mês a mês, opcionalmente restrito
        a um conjunto de lojas. Usado no lugar das abas por loja quando o
        relatório está filtrado por plano de contas."""
        if df_lanc.empty:
            return [0.0] * len(meses)
        bloco = df_lanc
        if lojas is not None:
            bloco = bloco[bloco["Loja"].isin(lojas)]
        if conta is not None:
            conta_norm = _normalizar_texto(conta)
            linhas_bloco = bloco["Linha DRE"].map(_normalizar_texto)
            if conta_norm == _normalizar_texto(ROTULO_FORA_DA_DRE):
                bloco = bloco[linhas_bloco == ""]
            else:
                bloco = bloco[linhas_bloco == conta_norm]
        return [float(bloco.loc[bloco["Mês"] == m_col, "Valor Bruto"].sum()) for m_col in meses]


    # ---- Planos de contas GLOBAIS por conta (juntando TODAS as lojas) ----
    # A aba "Plano de Contas" precisa mostrar sempre o MESMO conjunto de
    # planos de contas para uma dada linha da DRE, em todas as lojas -- com
    # valor ou não. Sem isso, uma loja que não tem lançamento pra um plano
    # específico simplesmente não mostrava aquela linha, enquanto outra loja
    # (que tem) mostrava -- deixando a estrutura inconsistente entre visões.
    planos_por_conta_global = {}
    if not df_lanc.empty:
        linhas_norm_geral = df_lanc["Linha DRE"].map(_normalizar_texto)
        for conta in contas_sel:
            conta_norm_geral = _normalizar_texto(conta)
            if conta_norm_geral == _normalizar_texto(ROTULO_FORA_DA_DRE):
                # Os planos sem linha da DRE ficam agrupados nessa pseudo-conta.
                planos_sem_linha = sorted(
                    df_lanc.loc[linhas_norm_geral == "", "Plano de Contas"].dropna().unique().tolist()
                )
                if planos_sem_linha:
                    planos_por_conta_global[conta] = planos_sem_linha
                continue
            mask_geral = linhas_norm_geral == conta_norm_geral
            if not mask_geral.any():
                mask_geral = linhas_norm_geral.apply(
                    lambda x: (conta_norm_geral in x) or (x in conta_norm_geral) if x else False
                )
            planos_conta = sorted(df_lanc.loc[mask_geral, "Plano de Contas"].dropna().unique().tolist())
            if planos_conta:
                planos_por_conta_global[conta] = planos_conta

    # ---------------- ABA "RESUMO" ----------------
    ws1 = wb.active
    ws1.title = "Resumo"

    _escrever_titulo(ws1, "Relatório de DRE — Orçado vs. Realizado (Resumo Anual)", 1, 5)
    # No recorte por plano de contas o orçamento não existe nesse nível --
    # ele é orçado por linha da DRE. Deixar a coluna zerada e dizer o porquê
    # é mais honesto do que comparar com um orçado que não é daquele plano.
    _legenda_resumo = gerado_em
    if planos_filtro:
        _legenda_resumo += (
            " · Recorte por plano de contas: " + ", ".join(planos_filtro)
            + " · Realizado só dos planos selecionados; Orçado é o da linha da DRE inteira "
            "(o orçamento não é detalhado por plano), e fica zerado nos planos sem linha da DRE"
        )
    _escrever_legenda(ws1, _legenda_resumo, 2, 5)

    linha_header = 4
    headers = ["Conta / Linha DRE", "Realizado (R$)", "Orçado (R$)", "Desvio (R$)", "Desvio (%)"]
    for col, texto in enumerate(headers, start=1):
        cell = ws1.cell(row=linha_header, column=col, value=texto)
        cell.font = EXCEL_STYLE["font_header"]
        cell.fill = EXCEL_STYLE["fill_header"]
        cell.border = EXCEL_STYLE["border"]
        cell.alignment = Alignment(horizontal="left" if col == 1 else "center", vertical="center")
    ws1.row_dimensions[linha_header].height = 20
    ws1.freeze_panes = f"A{linha_header + 1}"

    def _valores_conta_resumo(conta):
        if planos_filtro:
            v_real = sum(_valores_planos(conta, colunas_ano))
            # O orçamento existe por LINHA da DRE. Numa linha de verdade ele
            # aparece normalmente; só a pseudo-conta dos planos sem linha
            # fica zerada, porque ali não há o que comparar.
            v_orc = (
                0.0 if _normalizar_texto(conta) == _normalizar_texto(ROTULO_FORA_DA_DRE)
                else get_valor_consolidado_multi(dfs_orc, conta, colunas_ano)
            )
        else:
            v_real = get_valor_consolidado_multi(dfs_real, conta, colunas_ano)
            v_orc = get_valor_consolidado_multi(dfs_orc, conta, colunas_ano)
        return v_real, v_orc

    # Monta a sequência de linhas ANTES de escrever: primeiro cada bloco (o
    # subtotal e, recuadas, as linhas que o formam), com uma linha em branco
    # depois; no fim, o que sobrou fora dos blocos.
    linhas_resumo, contas_em_bloco = [], set()
    for bloco in blocos_agrupados:
        alvos = [c for c in contas_sel if c in bloco.get("linhas", [])]
        if not alvos:
            continue
        contas_em_bloco.update(alvos)
        valores_alvos = [_valores_conta_resumo(c) for c in alvos]
        linhas_resumo.append((
            bloco.get("titulo", "TOTAL"),
            sum(v[0] for v in valores_alvos),
            sum(v[1] for v in valores_alvos),
            True,
        ))
        for conta, (v_real, v_orc) in zip(alvos, valores_alvos):
            linhas_resumo.append((f"      {conta}", v_real, v_orc, False))
        linhas_resumo.append((None, None, None, False))

    for conta in contas_sel:
        if conta in contas_em_bloco:
            continue
        v_real, v_orc = _valores_conta_resumo(conta)
        linhas_resumo.append((conta, v_real, v_orc, False))

    # Linha de fechamento das coordenações: o EBITDA em % da receita líquida.
    # É a leitura que a operação usa -- o valor absoluto do EBITDA sobe junto
    # com a venda, e só o percentual mostra se a loja ficou mais ou menos
    # eficiente no mês.
    percentual_ebitda = None
    if linha_percentual_ebitda:
        linha_ebitda = next(
            (c for c in contas_sel if _numero_linha_dre(c) == str(GRUPO_EBITDA_DRE)), None
        )
        linha_receita = next((c for c in contas_sel if _numero_linha_dre(c) == "3"), None)
        if linha_ebitda and linha_receita:
            ebitda_real, ebitda_orc = _valores_conta_resumo(linha_ebitda)
            receita_real, receita_orc = _valores_conta_resumo(linha_receita)
            percentual_ebitda = (
                (ebitda_real / receita_real * 100) if receita_real else 0.0,
                (ebitda_orc / receita_orc * 100) if receita_orc else 0.0,
            )

    linha = linha_header + 1
    for i, (rotulo, v_real, v_orc, destaque) in enumerate(linhas_resumo):
        if rotulo is None:
            linha += 1
            continue
        desvio = v_real - v_orc
        desvio_pct = (desvio / abs(v_orc) * 100) if v_orc != 0 else 0.0

        # Fundo CLARO no subtotal: com o preenchimento escuro do cabeçalho,
        # o verde do desvio ficava ilegível. O destaque vem do negrito e do
        # tom azulado, e as cores de sinal continuam sendo lidas.
        fill = EXCEL_STYLE["fill_total"] if destaque else (
            EXCEL_STYLE["fill_zebra"] if i % 2 == 1 else None
        )
        valores = [rotulo, v_real, v_orc, desvio, desvio_pct]
        for col, val in enumerate(valores, start=1):
            cell = ws1.cell(row=linha, column=col, value=val)
            cell.border = EXCEL_STYLE["border"]
            if fill:
                cell.fill = fill
            if col == 1:
                cell.font = EXCEL_STYLE["font_bold"] if destaque else EXCEL_STYLE["font_normal"]
                cell.alignment = Alignment(horizontal="left", vertical="center")
            elif col in (2, 3):
                cell.font = EXCEL_STYLE["font_bold"] if destaque else EXCEL_STYLE["font_normal"]
                cell.number_format = '"R$" #,##0.00'
                cell.alignment = Alignment(horizontal="right")
            elif col == 4:
                cell.font = _fonte_por_valor(desvio, negrito=destaque)
                cell.number_format = '"R$" #,##0.00'
                cell.alignment = Alignment(horizontal="right")
            else:
                cell.font = _fonte_por_valor(desvio, negrito=destaque)
                cell.number_format = '0.0"%"'
                cell.alignment = Alignment(horizontal="right")
        linha += 1

    if percentual_ebitda is not None:
        # Uma linha em branco separando: ela não é uma conta como as de cima,
        # é a leitura percentual do fechamento.
        linha += 1
        real_pct, orc_pct = percentual_ebitda
        # O desvio aqui é em PONTOS PERCENTUAIS, não em reais nem em % do
        # orçado -- por isso a coluna de reais fica vazia. Escrever a
        # diferença de dois percentuais na coluna de R$ faria a soma da
        # coluna deixar de significar coisa alguma.
        valores_pct = ["11 - EBITDA (%)", real_pct, orc_pct, None, real_pct - orc_pct]
        for col, val in enumerate(valores_pct, start=1):
            cell = ws1.cell(row=linha, column=col, value=val)
            cell.border = EXCEL_STYLE["border"]
            cell.fill = EXCEL_STYLE["fill_total"]
            if col == 1:
                cell.font = EXCEL_STYLE["font_bold"]
                cell.alignment = Alignment(horizontal="left", vertical="center")
            elif col == 4:
                continue
            else:
                cell.font = (
                    EXCEL_STYLE["font_bold"] if col in (2, 3)
                    else _fonte_por_valor(real_pct - orc_pct, negrito=True)
                )
                cell.number_format = '0.0"%"'
                cell.alignment = Alignment(horizontal="right")
        linha += 1
        _escrever_legenda(
            ws1,
            "11 - EBITDA (%) = EBITDA dividido pela Receita Operacional Líquida. O desvio da "
            "última coluna está em pontos percentuais (realizado menos orçado), não em % do "
            "orçado como nas linhas acima.",
            linha, 5,
        )

    for col, largura in zip(range(1, 6), [46, 18, 18, 18, 14]):
        ws1.column_dimensions[get_column_letter(col)].width = largura

    # ---------------- ABA "DETALHE MENSAL" (Orçado x Realizado, por loja) ----------------
    # Formato tabular "achatado" (Loja/Conta/Tipo em colunas próprias, uma
    # linha por combinação) -- isso permite usar o AutoFilter nativo do
    # Excel na coluna "Loja" para escolher qual visão ver, sem precisar abrir
    # um arquivo gigante com tudo misturado. Clique na setinha do cabeçalho
    # da coluna "Loja" (linha 4) para filtrar.
    ws2 = wb.create_sheet("Detalhe Mensal")
    n_campos_dm = 3  # Loja, Conta, Tipo
    n_col_dm = n_campos_dm + n_meses + 1
    _escrever_titulo(ws2, "Detalhe Mensal — Orçado vs. Realizado, por Loja", 1, n_col_dm)
    _escrever_legenda(
        ws2,
        f"{gerado_em} · Use o filtro (▾) no cabeçalho da coluna \"Loja\" para escolher qual visão ver.",
        2, n_col_dm,
    )

    linha_header_dm = 4
    headers_dm = ["Loja", "Conta", "Tipo"] + [m.capitalize() for m in mapa_meses.keys()] + ["Total do período"]
    for col, texto in enumerate(headers_dm, start=1):
        cell = ws2.cell(row=linha_header_dm, column=col, value=texto)
        cell.font = EXCEL_STYLE["font_header"]
        cell.fill = EXCEL_STYLE["fill_header"]
        cell.border = EXCEL_STYLE["border"]
        cell.alignment = Alignment(horizontal="left" if col <= n_campos_dm else "center")
    ws2.row_dimensions[linha_header_dm].height = 20
    ws2.freeze_panes = f"D{linha_header_dm + 1}"

    linha = linha_header_dm + 1
    if not lojas_ordenadas:
        ws2.cell(row=linha, column=1, value="Nenhuma loja/unidade disponível para divisão.").font = EXCEL_STYLE["font_normal"]
        linha += 1
    for loja in lojas_ordenadas:
        df_o_loja, df_r_loja = dados_por_loja[loja]

        lojas_do_bloco = (
            [loja] if _normalizar_nome_aba(loja) not in _LOJAS_CONSOLIDADAS_NORM
            else _lojas_do_grupo_consolidado(loja)
        )
        def _valores_conta_mes(conta):
            if planos_filtro:
                valores_real = _valores_planos(conta, list(mapa_meses.values()), lojas_do_bloco)
                # Linha da DRE de verdade mantém o orçado dela; a pseudo-conta
                # dos planos sem linha fica zerada.
                if _normalizar_texto(conta) == _normalizar_texto(ROTULO_FORA_DA_DRE):
                    valores_orc = [0.0] * len(mapa_meses)
                else:
                    valores_orc = [
                        get_valor_consolidado_multi([df_o_loja], conta, [m_col])
                        for m_col in mapa_meses.values()
                    ]
            else:
                valores_real = [get_valor_consolidado_multi([df_r_loja], conta, [m_col]) for m_col in mapa_meses.values()]
                valores_orc = [get_valor_consolidado_multi([df_o_loja], conta, [m_col]) for m_col in mapa_meses.values()]
            return valores_real, valores_orc

        def _escrever_trio(rotulo_conta, valores_real, valores_orc):
            nonlocal linha
            valores_desvio = [vr - vo for vr, vo in zip(valores_real, valores_orc)]
            _escrever_linha_flat(ws2, linha, [loja, rotulo_conta, "Realizado"], valores_real, sum(valores_real))
            linha += 1
            _escrever_linha_flat(ws2, linha, [loja, rotulo_conta, "Orçado"], valores_orc, sum(valores_orc), fill=EXCEL_STYLE["fill_zebra"])
            linha += 1
            _escrever_linha_flat(ws2, linha, [loja, rotulo_conta, "Desvio"], valores_desvio, sum(valores_desvio), colorir_por_sinal=True)
            linha += 1

        # Mesma separação do Resumo: o subtotal do bloco vem primeiro, depois
        # as linhas que o compõem, e só então o restante das contas.
        contas_em_bloco_dm = set()
        for bloco in blocos_agrupados:
            alvos = [c for c in contas_sel if c in bloco.get("linhas", [])]
            if not alvos:
                continue
            contas_em_bloco_dm.update(alvos)
            valores_alvos = [_valores_conta_mes(c) for c in alvos]
            soma_real = [sum(v[0][i] for v in valores_alvos) for i in range(len(mapa_meses))]
            soma_orc = [sum(v[1][i] for v in valores_alvos) for i in range(len(mapa_meses))]
            _escrever_trio(bloco.get("titulo", "TOTAL"), soma_real, soma_orc)
            for conta, (valores_real, valores_orc) in zip(alvos, valores_alvos):
                _escrever_trio(f"      {conta}", valores_real, valores_orc)

        for conta in contas_sel:
            if conta in contas_em_bloco_dm:
                continue
            valores_real, valores_orc = _valores_conta_mes(conta)
            _escrever_trio(conta, valores_real, valores_orc)

    ultima_linha_dm = linha - 1
    largura_mes = 14
    ws2.column_dimensions["A"].width = 26
    ws2.column_dimensions["B"].width = 40
    ws2.column_dimensions["C"].width = 12
    for col in range(n_campos_dm + 1, n_col_dm + 1):
        ws2.column_dimensions[get_column_letter(col)].width = largura_mes
    if ultima_linha_dm >= linha_header_dm + 1:
        ws2.auto_filter.ref = f"A{linha_header_dm}:{get_column_letter(n_col_dm)}{ultima_linha_dm}"

    # ---------------- ABA "PLANO DE CONTAS" (composição de cada linha da DRE, por loja) ----------------
    # Mesmo formato tabular achatado, com AutoFilter na coluna "Loja".
    ws3 = wb.create_sheet("Plano de Contas")
    n_campos_pc = 3  # Loja, Conta, Plano de Contas
    n_col_pc = n_campos_pc + n_meses + 1
    _escrever_titulo(ws3, "Plano de Contas — Composição das Linhas da DRE, por Loja", 1, n_col_pc)
    _escrever_legenda(
        ws3,
        f"{gerado_em} · Valores de cada plano de contas puxados da DIÁRIO (Realizado), pela loja/Centro "
        f"de Custos. Visões consolidadas somam as lojas individuais correspondentes. Use o filtro (▾) no "
        f"cabeçalho da coluna \"Loja\" para escolher qual visão ver.",
        2, n_col_pc,
    )

    linha_header_pc = 4
    headers_pc = ["Loja", "Conta", "Plano de Contas"] + [m.capitalize() for m in mapa_meses.keys()] + ["Total do período"]
    for col, texto in enumerate(headers_pc, start=1):
        cell = ws3.cell(row=linha_header_pc, column=col, value=texto)
        cell.font = EXCEL_STYLE["font_header"]
        cell.fill = EXCEL_STYLE["fill_header"]
        cell.border = EXCEL_STYLE["border"]
        cell.alignment = Alignment(horizontal="left" if col <= n_campos_pc else "center")
    ws3.row_dimensions[linha_header_pc].height = 20
    ws3.freeze_panes = f"D{linha_header_pc + 1}"

    linha = linha_header_pc + 1
    if not lojas_ordenadas:
        ws3.cell(row=linha, column=1, value="Nenhuma loja/unidade disponível para divisão.").font = EXCEL_STYLE["font_normal"]
        linha += 1

    indice_grupo = 0
    for loja in lojas_ordenadas:
        df_o_loja, df_r_loja = dados_por_loja[loja]

        # Lançamentos desta loja -- ou, se for uma visão consolidada, de
        # todas as lojas individuais que fazem parte dela.
        if _normalizar_nome_aba(loja) in _LOJAS_CONSOLIDADAS_NORM:
            lojas_do_grupo = _lojas_do_grupo_consolidado(loja)
            df_lanc_loja = df_lanc[df_lanc["Loja"].isin(lojas_do_grupo)] if lojas_do_grupo else df_lanc.iloc[0:0]
        else:
            df_lanc_loja = df_lanc[df_lanc["Loja"] == loja]

        for conta in contas_sel:
            # Cada conta (linha da DRE) forma um "grupo" -- as linhas de
            # plano de contas dela, mais o TOTAL, recebem o mesmo
            # sombreamento leve alternado, pra ficar visualmente claro onde
            # um grupo termina e o próximo começa (em vez de tudo num fundo
            # branco igual, que se perde fácil numa planilha grande).
            indice_grupo += 1
            fill_grupo = EXCEL_STYLE["fill_group"] if indice_grupo % 2 == 1 else None
            df_diario_conta = pd.DataFrame()
            if not df_lanc_loja.empty:
                conta_norm = _normalizar_texto(conta)
                linhas_norm_loja = df_lanc_loja["Linha DRE"].map(_normalizar_texto)
                if conta_norm == _normalizar_texto(ROTULO_FORA_DA_DRE):
                    # Pseudo-conta dos planos sem linha da DRE: o filtro é a
                    # ausência de linha, não o nome dela.
                    df_diario_conta = df_lanc_loja[linhas_norm_loja == ""]
                else:
                    mask_conta_loja = linhas_norm_loja == conta_norm
                    if not mask_conta_loja.any():
                        mask_conta_loja = linhas_norm_loja.apply(lambda x: (conta_norm in x) or (x in conta_norm) if x else False)
                    df_diario_conta = df_lanc_loja[mask_conta_loja]

            soma_planos_mes = [0.0] * n_meses
            planos_globais_conta = planos_por_conta_global.get(conta)
            if planos_globais_conta:
                # Fonte principal: DIÁRIO/Lançamentos. Usa o conjunto GLOBAL
                # de planos de contas dessa linha da DRE (calculado juntando
                # todas as lojas) -- assim TODA loja mostra as mesmas linhas
                # de plano de contas, mesmo que, para essa loja específica,
                # o valor seja zero (sem lançamento).
                for plano in planos_globais_conta:
                    grupo = df_diario_conta[df_diario_conta["Plano de Contas"] == plano] if not df_diario_conta.empty else df_diario_conta
                    valores_plano = (
                        [grupo.loc[grupo["Mês"] == m_col, "Valor Bruto"].sum() for m_col in mapa_meses.values()]
                        if not grupo.empty else [0.0] * n_meses
                    )
                    soma_planos_mes = [s + v for s, v in zip(soma_planos_mes, valores_plano)]
                    _escrever_linha_flat(ws3, linha, [loja, conta, plano], valores_plano, sum(valores_plano), fill=fill_grupo)
                    linha += 1
                n_planos_escritos = len(planos_globais_conta)
            elif permitir_lancamento_manual and not (mapa_planos_dre.get(str(conta).strip(), [])):
                # Linha DRE sem nenhum Plano de Contas correspondente (nem no
                # DIÁRIO, nem na Tabela_Contas) -- típico do modelo de RH.
                valores_manual = [
                    get_valor_consolidado_multi([df_r_loja], conta, [m_col]) for m_col in mapa_meses.values()
                ]
                soma_planos_mes = valores_manual
                _escrever_linha_flat(ws3, linha, [loja, conta, "Lançado Manualmente"], valores_manual, sum(valores_manual), fill=fill_grupo)
                linha += 1
                n_planos_escritos = 1
            else:
                # Fallback: Tabela_Contas + soma nas abas por loja (método antigo).
                planos = mapa_planos_dre.get(str(conta).strip(), []) or [conta]
                conta_norm_cmp = _normalizar_texto(conta)
                for plano in planos:
                    valores_plano = [
                        get_valor_consolidado_multi([df_r_loja], plano, [m_col]) for m_col in mapa_meses.values()
                    ]
                    soma_planos_mes = [s + v for s, v in zip(soma_planos_mes, valores_plano)]
                    # Quando não há um Plano de Contas distinto de verdade
                    # (caiu no fallback "ou [conta]", ou a Tabela_Contas só
                    # tem o próprio nome da linha da DRE como "plano"), o
                    # valor já vem certo, mas o rótulo repetia a conta --
                    # mostramos "Lançado Manualmente" para deixar claro que
                    # esse valor foi lançado direto na linha da DRE, sem
                    # composição por plano de contas. Vale para qualquer
                    # modelo de relatório, não só o de RH.
                    rotulo_plano = "Lançado Manualmente" if _normalizar_texto(plano) == conta_norm_cmp else plano
                    _escrever_linha_flat(ws3, linha, [loja, conta, rotulo_plano], valores_plano, sum(valores_plano), fill=fill_grupo)
                    linha += 1
                n_planos_escritos = len(planos)

            # A linha de TOTAL só faz sentido (e só é escrita) quando há MAIS
            # DE UM plano de contas para essa linha da DRE -- com um único
            # plano, o total seria idêntico à própria linha, repetindo o
            # mesmo valor à toa. O rótulo cita a própria conta ("TOTAL —
            # <conta>") para deixar explícito a quais linhas de plano de
            # contas, logo acima, aquele total se refere -- em vez de
            # depender só da cor de fundo pra não se perder na leitura.
            if n_planos_escritos > 1:
                _escrever_linha_flat(
                    ws3, linha, [loja, conta, f"TOTAL — {conta}"], soma_planos_mes, sum(soma_planos_mes),
                    negrito=True, fill=EXCEL_STYLE["fill_total"],
                )
                linha += 1

        if forcar_planos_contas:
            # Planos de contas que fazem parte do modelo mas não têm Linha DRE
            # correspondente (ex.: "Mercadorias" no modelo de Compras) --
            # puxados direto da DIÁRIO/Lançamentos pelo nome do plano,
            # ignorando a Linha DRE.
            indice_grupo += 1
            fill_grupo_forcado = EXCEL_STYLE["fill_group"] if indice_grupo % 2 == 1 else None
            soma_forcados_mes = [0.0] * n_meses
            for plano_forcado in forcar_planos_contas:
                df_plano_forcado = pd.DataFrame()
                if not df_lanc_loja.empty:
                    plano_norm = _normalizar_texto(plano_forcado)
                    planos_norm_loja = df_lanc_loja["Plano de Contas"].map(_normalizar_texto)
                    mask_plano = planos_norm_loja == plano_norm
                    if not mask_plano.any():
                        mask_plano = planos_norm_loja.apply(lambda x: (plano_norm in x) or (x in plano_norm) if x else False)
                    df_plano_forcado = df_lanc_loja[mask_plano]

                valores_plano = (
                    [df_plano_forcado.loc[df_plano_forcado["Mês"] == m_col, "Valor Bruto"].sum() for m_col in mapa_meses.values()]
                    if not df_plano_forcado.empty else [0.0] * n_meses
                )
                soma_forcados_mes = [s + v for s, v in zip(soma_forcados_mes, valores_plano)]
                _escrever_linha_flat(
                    ws3, linha, [loja, "(Fora da DRE)", plano_forcado], valores_plano, sum(valores_plano),
                    fill=fill_grupo_forcado,
                )
                linha += 1

            if len(forcar_planos_contas) > 1:
                _escrever_linha_flat(
                    ws3, linha, [loja, "(Fora da DRE)", "TOTAL — Fora da DRE"], soma_forcados_mes, sum(soma_forcados_mes),
                    negrito=True, fill=EXCEL_STYLE["fill_total"],
                )
                linha += 1

    ultima_linha_pc = linha - 1
    ws3.column_dimensions["A"].width = 26
    ws3.column_dimensions["B"].width = 40
    ws3.column_dimensions["C"].width = 42
    for col in range(n_campos_pc + 1, n_col_pc + 1):
        ws3.column_dimensions[get_column_letter(col)].width = largura_mes
    if ultima_linha_pc >= linha_header_pc + 1:
        ws3.auto_filter.ref = f"A{linha_header_pc}:{get_column_letter(n_col_pc)}{ultima_linha_pc}"

    # ---------------- ABA "LANÇAMENTOS" (cópia filtrada da DIÁRIO) ----------------
    ws4 = wb.create_sheet("Lançamentos")
    N_COL_LANC = 9
    _escrever_titulo(ws4, "Lançamentos — Cópia filtrada da aba DIÁRIO (Realizado)", 1, N_COL_LANC)
    _escrever_legenda(
        ws4,
        f"{gerado_em} · {len(df_lanc)} lançamento(s): linhas cujo Plano de Contas pertence às linhas "
        f"da DRE deste relatório, ou aos planos adicionais do modelo (ex.: Mercadorias).",
        2, N_COL_LANC,
    )

    linha = 4
    headers_lanc = [
        "Loja", "Competência", "Número", "Centro de Custos", "Linha DRE",
        "Plano de Contas", "Cliente / Fornecedor", "Histórico", "Valor Bruto (R$)",
    ]
    col_valor_lanc = len(headers_lanc)
    for col, texto in enumerate(headers_lanc, start=1):
        cell = ws4.cell(row=linha, column=col, value=texto)
        cell.font = EXCEL_STYLE["font_header"]
        cell.fill = EXCEL_STYLE["fill_header"]
        cell.border = EXCEL_STYLE["border"]
        cell.alignment = Alignment(horizontal="left" if col < col_valor_lanc else "center")
    ws4.row_dimensions[linha].height = 20
    ws4.freeze_panes = f"A{linha + 1}"
    linha += 1

    if not df_lanc.empty:
        df_lanc_ordenado = df_lanc.sort_values(["Loja", "Competência"], na_position="last")
        for i, (_, row) in enumerate(df_lanc_ordenado.iterrows()):
            data_val = row["Competência"]
            data_txt = data_val.strftime("%d/%m/%Y") if pd.notna(data_val) and hasattr(data_val, "strftime") else str(data_val)
            valores = [
                row["Loja"], data_txt, row.get("Número", ""), row["Centro de Custos"], row["Linha DRE"],
                row["Plano de Contas"], row.get("Cliente / Fornecedor", ""), row.get("Histórico", ""), row["Valor Bruto"],
            ]
            fill = EXCEL_STYLE["fill_zebra"] if i % 2 == 1 else None
            for col, val in enumerate(valores, start=1):
                cell = ws4.cell(row=linha, column=col, value=val)
                cell.border = EXCEL_STYLE["border"]
                if fill:
                    cell.fill = fill
                if col == col_valor_lanc:
                    cell.font = EXCEL_STYLE["font_normal"]
                    cell.number_format = '"R$" #,##0.00'
                    cell.alignment = Alignment(horizontal="right")
                else:
                    cell.font = EXCEL_STYLE["font_normal"]
                    cell.alignment = Alignment(horizontal="left")
            linha += 1

        # AutoFilter nativo do Excel -- cobre só cabeçalho + linhas de dados
        # (não a linha de TOTAL, escrita logo abaixo).
        ws4.auto_filter.ref = f"A4:{get_column_letter(N_COL_LANC)}{linha - 1}"

        total_lanc = df_lanc["Valor Bruto"].sum()
        cell_total_lbl = ws4.cell(row=linha, column=1, value="TOTAL")
        cell_total_lbl.font = EXCEL_STYLE["font_bold"]
        cell_total = ws4.cell(row=linha, column=col_valor_lanc, value=total_lanc)
        cell_total.font = EXCEL_STYLE["font_bold"]
        cell_total.number_format = '"R$" #,##0.00'
        cell_total.alignment = Alignment(horizontal="right")
        for col in range(1, N_COL_LANC + 1):
            ws4.cell(row=linha, column=col).fill = EXCEL_STYLE["fill_total"]
            ws4.cell(row=linha, column=col).border = EXCEL_STYLE["border"]
    else:
        ws4.cell(
            row=linha, column=1,
            value="Nenhum lançamento encontrado (DIÁRIO indisponível ou sem correspondência para os filtros deste relatório).",
        ).font = EXCEL_STYLE["font_normal"]

    ws4.column_dimensions["A"].width = 24
    ws4.column_dimensions["B"].width = 14
    ws4.column_dimensions["C"].width = 14
    ws4.column_dimensions["D"].width = 20
    ws4.column_dimensions["E"].width = 30
    ws4.column_dimensions["F"].width = 30
    ws4.column_dimensions["G"].width = 28
    ws4.column_dimensions["H"].width = 40
    ws4.column_dimensions["I"].width = 18

    # ---------------- ABA "MKT - 1% x OUTRAS DESPESAS" (só no modelo de MKT) ----------------
    # Layout fixo, independente das linhas/lojas selecionadas: sempre a linha
    # 6.24.2 nas quatro visões consolidadas. Por isso recebe os dados por
    # `dados_visoes_mkt` (carregado à parte, garantindo as quatro abas) e só
    # cai para `dados_por_loja` se, por algum motivo, ele não vier.
    if incluir_aba_mkt_1pct:
        _criar_aba_mkt_1pct(wb, dados_visoes_mkt or dados_por_loja, mapa_meses, gerado_em)

    # ---------------- ABAS "ANUAL - <visão>" (coordenações) ----------------
    # Uma por visão consolidada do departamento. Ficam por último para não
    # empurrar as abas de sempre para o fim do arquivo.
    if resumos_anuais:
        nomes_usados_anual = {ws.title for ws in wb.worksheets}
        for nome_visao in resumos_anuais:
            dados_visao = (dados_por_loja or {}).get(nome_visao)
            if not dados_visao:
                continue
            df_o_visao, df_r_visao = dados_visao
            _criar_aba_resumo_anual(
                wb, nomes_usados_anual, nome_visao, df_o_visao, df_r_visao,
                mapa_meses_anual or mapa_meses, contas_sel, gerado_em,
            )

    buffer = io.BytesIO()
    wb.save(buffer)
    buffer.seek(0)
    return buffer.getvalue()


# ============================================================================
# 7. FAIXA DE CONTEXTO (fina — não repete um bloco grande em toda aba)
